// Seibutsu: generated by AWAI-3079 gen_appdef.py from src/domain, then reviewed.
// Every action runs the domain code on this device against the local store.
import { registerTaxon, getTaxon, listTaxa, deriveTraits, listTraits, ingestObservation, listObservations, coverage } from "./domain/index.js";
import presets from "./domain/preset-taxa.js";

export const app = {
  title: "Seibutsu",
  description: "生物 — 生物分類（taxon）と形質（traits）と観察記録を扱う、公開データ型の生物多様性カタログです。画像からの種の同定（推論）は含みません。",
  did: "did:web:seibutsu.itonami.cloud",
  storageKey: "itonami.seibutsu.v1",
  collections: [
    { name: "cloud.itonami.apps.seibutsu.observation", label: "observation" },
    { name: "cloud.itonami.apps.seibutsu.taxon", label: "taxon" },
    { name: "cloud.itonami.apps.seibutsu.traits", label: "traits" },
  ],
  actions: [
    { name: "registerTaxon", label: "分類を登録 (registerTaxon)", help: "親の分類（parentTaxonId）は先に登録しておく必要があります。",
      fields: [
        {"name": "taxonId", "label": "taxonId", "required": true},
        {"name": "rank", "label": "rank", "required": true, "type": "select", "options": ["domain", "kingdom", "phylum", "class", "order", "family", "genus", "species", "subspecies", "other"]},
        {"name": "scientificName", "label": "scientificName", "required": true},
        {"name": "commonName", "label": "commonName"},
        {"name": "parentTaxonId", "label": "parentTaxonId"},
        {"name": "gbifId", "label": "gbifId"},
        {"name": "ncbiId", "label": "ncbiId"},
        {"name": "wikidataId", "label": "wikidataId"},
        {"name": "sourceUrl", "label": "sourceUrl"}
      ],
      run: (store, input) => registerTaxon(store, input) },
    { name: "getTaxon", label: "分類を見る (getTaxon)",
      fields: [
        {"name": "taxonId", "label": "taxonId", "required": true}
      ],
      run: (store, input) => getTaxon(store, input) },
    { name: "listTaxa", label: "分類の一覧 (listTaxa)",
      fields: [
        {"name": "rank", "label": "rank", "type": "select", "options": ["domain", "kingdom", "phylum", "class", "order", "family", "genus", "species", "subspecies", "other"]},
        {"name": "parentTaxonId", "label": "parentTaxonId"},
        {"name": "q", "label": "q"},
        {"name": "limit", "label": "limit", "type": "number"},
        {"name": "cursor", "label": "cursor"}
      ],
      run: (store, input) => listTaxa(store, input) },
    { name: "deriveTraits", label: "形質を記録 (deriveTraits)",
      fields: [
        {"name": "traitId", "label": "traitId", "required": true},
        {"name": "taxonId", "label": "taxonId", "required": true},
        {"name": "habit", "label": "habit", "required": true, "type": "select", "options": ["tree", "shrub", "herb", "grass", "vine", "fungus", "other"]},
        {"name": "matureHeightCm", "label": "matureHeightCm", "type": "number"},
        {"name": "lifespanYears", "label": "lifespanYears", "type": "number"},
        {"name": "hardinessZone", "label": "hardinessZone"},
        {"name": "sourceUrl", "label": "sourceUrl"}
      ],
      run: (store, input) => deriveTraits(store, input) },
    { name: "listTraits", label: "形質の一覧 (listTraits)",
      fields: [
        {"name": "taxonId", "label": "taxonId"},
        {"name": "habit", "label": "habit", "type": "select", "options": ["tree", "shrub", "herb", "grass", "vine", "fungus", "other"]},
        {"name": "limit", "label": "limit", "type": "number"},
        {"name": "cursor", "label": "cursor"}
      ],
      run: (store, input) => listTraits(store, input) },
    { name: "ingestObservation", label: "観察を記録 (ingestObservation)",
      fields: [
        {"name": "observationId", "label": "observationId", "required": true},
        {"name": "taxonId", "label": "taxonId", "required": true},
        {"name": "observedAt", "label": "observedAt", "required": true},
        {"name": "geoH3", "label": "geoH3"},
        {"name": "observerHandle", "label": "observerHandle"},
        {"name": "imageUrl", "label": "imageUrl"},
        {"name": "sourceUrl", "label": "sourceUrl"}
      ],
      run: (store, input) => ingestObservation(store, input) },
    { name: "listObservations", label: "観察の一覧 (listObservations)",
      fields: [
        {"name": "taxonId", "label": "taxonId"},
        {"name": "geoH3", "label": "geoH3"},
        {"name": "observerHandle", "label": "observerHandle"},
        {"name": "limit", "label": "limit", "type": "number"},
        {"name": "cursor", "label": "cursor"}
      ],
      run: (store, input) => listObservations(store, input) },
    { name: "coverage", label: "記録の数 (coverage)",
      fields: [
        {"name": "maxScan", "label": "maxScan", "type": "number"}
      ],
      run: (store, input) => coverage(store, input) },
    { name: "loadPresetTaxa", label: "プリセットの分類を読み込む", help: "kami-vegetation の 7 科（と親の 4 門）を、分類と形質としてこの端末に登録します。登録済みのものはそのままにします。",
      fields: [],
      run: async (store) => {
        const HABITS = ["tree", "shrub", "herb", "grass", "vine", "fungus", "other"];
        const slug = (did) => did.split(":").pop();
        const results = [];
        // Parent groups are botanical divisions, i.e. rank "phylum".
        for (const parent of [...new Set(presets.taxa.map((t) => t.taxon.parentDid).filter(Boolean))]) {
          const id = slug(parent);
          const r = await registerTaxon(store, { taxonId: id, rank: "phylum", scientificName: id.charAt(0).toUpperCase() + id.slice(1) });
          results.push({ taxonId: id, status: r.status });
        }
        for (const { taxon, traits } of presets.taxa) {
          const id = slug(taxon.did);
          const r = await registerTaxon(store, { taxonId: id, rank: taxon.rank, scientificName: taxon.scientificName, commonName: taxon.commonName, parentTaxonId: taxon.parentDid ? slug(taxon.parentDid) : undefined, gbifId: taxon.gbifId });
          // heightRange in the preset is a relative render scale, not centimetres, so it is not mapped.
          const t = await deriveTraits(store, { traitId: id, taxonId: id, habit: HABITS.includes(traits.habit) ? traits.habit : "other" });
          results.push({ taxonId: id, taxon: r.status, traits: t.status });
        }
        return { loaded: results };
      } },
  ],
};
